package codesign

import (
	_ "embed"
	"encoding/json"
	"fmt"
)

// Verified RS decoder results (G4). Single source: generated by
// platform/scripts/gen_codesign_verified.py — every figure measured live
// from the builders (emitter-speed; proofs ran at slice-landing and are
// cited, not re-run). The generator fails loudly on drift, so this file
// can only ever contain pin-verified numbers. Served verbatim: Go serves
// numbers, never verdicts (validity stays Python-owned).

//go:embed verified.json
var verifiedJSON []byte

// VerifiedReport is the served shape (mirrors verified.json).
type VerifiedReport struct {
	Program   string   `json:"program"`
	Version   int      `json:"version"`
	Generated string   `json:"generated"`
	Generator string   `json:"generator"`
	Labels    []string `json:"labels"`
	Total     struct {
		Toffoli int    `json:"toffoli"`
		Qubits  int    `json:"qubits"`
		Pin     string `json:"pin"`
	} `json:"total"`
	Components []struct {
		Name    string `json:"name"`
		Toffoli int    `json:"toffoli"`
		Scope   string `json:"scope"`
		Pin     string `json:"pin"`
	} `json:"components"`
	Proofs []string `json:"proofs"`
}

// ParseVerifiedReport decodes the embedded report (fail-closed on skew
// between the JSON and this struct — a shape change refuses loudly).
func ParseVerifiedReport() (VerifiedReport, error) {
	var r VerifiedReport
	if err := json.Unmarshal(verifiedJSON, &r); err != nil {
		return r, fmt.Errorf("verified report corrupt: refusing (%v)", err)
	}
	if r.Total.Toffoli <= 0 || r.Total.Qubits <= 0 || len(r.Components) == 0 {
		return r, fmt.Errorf("verified report incomplete: refusing")
	}
	return r, nil
}

// VerifiedJSON returns the raw embedded document (served verbatim).
func VerifiedJSON() []byte {
	return verifiedJSON
}
